  objectLevelWorm is ArmResourceActionAsync<
    BlobContainer,
    void,
    {
      @body body: void;
    },
    Error = CloudError,
    LroHeaders = Azure.Core.Foundations.RetryAfterHeader &
      ArmLroLocationHeader<FinalResult = void>
  >

